class Solution {
    public int[][] merge(int[][] intervals) {
        // Step 1: Sort by start time -> overlapping intervals become adjacent
        Arrays.sort(intervals, (a, b) -> Integer.compare(a[0], b[0]));

        List<int[]> result = new ArrayList<>();
        // Start with the first interval as the current merge window
        int[] current = intervals[0];

        for (int i = 1; i < intervals.length; i++) {
            // Check if current interval overlaps with the merge window
            if (intervals[i][0] <= current[1]) {
                // Overlap -> extend the window (take union: max of ends)
                current[1] = Math.max(current[1], intervals[i][1]);
            } else {
                // No overlap -> finalize current window, start fresh
                result.add(current);
                current = intervals[i];
            }
        }
        result.add(current); // Don't forget the last window
        return result.toArray(new int[result.size()][]);
    }
}

class Solution {
    public int findMinArrowShots(int[][] points) {
        // Sort by END -> earliest-closing balloon is most constrained
        Arrays.sort(points, (a, b) -> Integer.compare(a[1], b[1]));

        // First arrow fires at the end of the first balloon
        int end   = points[0][1];
        int count = 1;

        for (int i = 1; i < points.length; i++) {
            int currStart = points[i][0];
            int currEnd   = points[i][1];

            if (currStart <= end) {
                // Overlap: tighten the window to intersection (not union!)
                // Math.min because sorted by end, currEnd >= end always,
                // so this just keeps end unchanged -- but the pattern is min.
                end = Math.min(currEnd, end);
            } else {
                // No overlap: fire a new arrow at this balloon's end
                end = currEnd;
                count++;
            }
        }
        return count;
    }
}

class Solution {
    public int eraseOverlapIntervals(int[][] intervals) {
        // Sort by end: keep the interval that ends earliest (greedy)
        Arrays.sort(intervals, (a, b) -> Integer.compare(a[1], b[1]));

        int kept = 1;
        int lastEnd = intervals[0][1]; // end of the last kept interval

        for (int i = 1; i < intervals.length; i++) {
            if (intervals[i][0] >= lastEnd) {
                // No overlap with last kept interval -> keep this one
                kept++;
                lastEnd = intervals[i][1];
            }
            // Else: overlap -> discard current (keep the one ending earlier)
        }
        return intervals.length - kept; // minimum removals
    }
}

class MyCalendarThree {
    // Difference map: sorted time points with net change at each point
    // key = time point (TreeMap keeps them sorted automatically)
    // value = +1 (event starts) or -1 (event ends), accumulated
    private TreeMap<Integer, Integer> diff;

    public MyCalendarThree() {
        diff = new TreeMap<>();
    }

    public int book(int startTime, int endTime) {
        // Event becomes active at startTime
        diff.put(startTime, diff.getOrDefault(startTime, 0) + 1);
        // Event stops at endTime (exclusive interval [start, end))
        diff.put(endTime, diff.getOrDefault(endTime, 0) - 1);

        int maxK    = 0; // peak overlap seen across entire timeline
        int current = 0; // running overlap as we sweep left -> right

        for (int delta : diff.values()) {
            current += delta;               // apply change (+1 or -1)
            maxK = Math.max(maxK, current); // freeze the peak
        }
        return maxK; // maximum k-booking
    }
}

class Solution {
    public int minMeetingRooms(int[][] intervals) {
        // Two separate sorted arrays: all starts and all ends
        int n = intervals.length;
        int[] starts = new int[n];
        int[] ends   = new int[n];

        for (int i = 0; i < n; i++) {
            starts[i] = intervals[i][0];
            ends[i]   = intervals[i][1];
        }
        Arrays.sort(starts);
        Arrays.sort(ends);

        int rooms = 0, maxRooms = 0;
        int e = 0; // pointer into ends array

        for (int s = 0; s < n; s++) {
            if (starts[s] < ends[e]) {
                // New meeting starts before any current meeting ends -> need new room
                rooms++;
            } else {
                // A meeting has ended -> reuse its room (advance end pointer)
                e++;
            }
            maxRooms = Math.max(maxRooms, rooms);
        }
        return maxRooms;
    }
}

class Solution {
    public boolean canAttendMeetings(int[][] intervals) {
        // Sort by start -- if any meeting starts before the previous ends, conflict
        Arrays.sort(intervals, (a, b) -> Integer.compare(a[0], b[0]));

        for (int i = 1; i < intervals.length; i++) {
            // Previous meeting hasn't ended when this one starts -> conflict
            if (intervals[i][0] < intervals[i-1][1]) {
                return false;
            }
        }
        return true;
    }
}

class MyCalendar {
    // Store all booked intervals
    private TreeMap<Integer, Integer> calendar;

    public MyCalendar() {
        calendar = new TreeMap<>();
    }

    public boolean book(int start, int end) {
        // Find the largest start <= new start (could overlap from the left)
        Map.Entry<Integer, Integer> prev = calendar.floorEntry(start);
        // Find the smallest start >= new start (could overlap from the right)
        Map.Entry<Integer, Integer> next = calendar.ceilingEntry(start);

        // prev overlaps if its end > new start
        // next overlaps if new end > next's start
        if ((prev == null || prev.getValue() <= start) &&
            (next == null || end <= next.getKey())) {
            calendar.put(start, end);
            return true;
        }
        return false;
    }
}

class SummaryRanges {
    // TreeMap: start -> end of each disjoint interval
    private TreeMap<Integer, Integer> intervals;

    public SummaryRanges() {
        intervals = new TreeMap<>();
    }

    public void addNum(int value) {
        int start = value, end = value;

        // Check if previous interval can merge (its end >= value - 1)
        Map.Entry<Integer, Integer> prev = intervals.floorEntry(value);
        if (prev != null && prev.getValue() >= value - 1) {
            start = prev.getKey();       // extend left
            end   = Math.max(end, prev.getValue());
            intervals.remove(prev.getKey());
        }

        // Check if next interval can merge (its start <= value + 1)
        Map.Entry<Integer, Integer> next = intervals.ceilingEntry(value);
        if (next != null && next.getKey() <= value + 1) {
            end = Math.max(end, next.getValue()); // extend right
            intervals.remove(next.getKey());
        }

        intervals.put(start, end); // insert merged interval
    }

    public int[][] getIntervals() {
        int[][] result = new int[intervals.size()][2];
        int i = 0;
        for (Map.Entry<Integer, Integer> e : intervals.entrySet()) {
            result[i][0] = e.getKey();
            result[i][1] = e.getValue();
            i++;
        }
        return result;
    }
}
